import re,os,json,yaml
B=os.path.expanduser('~/mnt/explora-next/content/guias/')
def rd(p): return open(B+p,encoding='utf-8').read()
def wr(p,s): open(B+p,'w',encoding='utf-8').write(s)
def setdate(s): return re.sub(r"fecha_actualizacion: '?[0-9-]+'?","fecha_actualizacion: '2026-11-10'",s,1)
def addfaq(s,q,a):
    L=s.split('\n'); end=[i for i,l in enumerate(L) if l=='---' and i>0][0]
    idx=max(i for i in range(end) if L[i].lstrip().startswith('respuesta:'))
    ind=L[idx][:len(L[idx])-len(L[idx].lstrip())]
    L[idx+1:idx+1]=[ind[:-2]+'- pregunta: '+json.dumps(q,ensure_ascii=False), ind+'respuesta: '+json.dumps(a,ensure_ascii=False)]
    s='\n'.join(L); assert len(yaml.safe_load(s.split('---')[1])['faq'])==6; return s
def lastH2(s): return [m.start() for m in re.finditer(r'^## ',s,re.M)][-1]
def tab(h,cols,rows,bul,note):
    return h+'\n\n| '+' | '.join(cols)+' |\n| '+' | '.join(['---']*len(cols))+' |\n'+''.join('| '+' | '.join(r)+' |\n' for r in rows)+'\n'+''.join('- '+b+'\n' for b in bul)+'\n'+note+'\n\n'
